 {
  "name": "README",
  "src": "10 rem *** read me ***\n20 poke 53280,14:poke 53281,6:p=1:q$=chr$(34)\n30 print \"{147}{154}\"\n40 on p goto 100,200,300,400\n50 end\n100 print \" WELCOME TO YOUR COMMODORE 64\":print\n110 print \"{5} TYPE BASIC LINES WITH A LINE NUMBER:\":print\n120 print \"{158}  10 PRINT \";q$;\"HELLO\";q$\n130 print \"  20 GOTO 10\":print \"{5}\"\n140 print \" THEN TYPE RUN. PRESS RUN/STOP (ESC)\"\n150 print \" TO BREAK. TYPE LIST TO SEE IT.\":print\n160 print \" NO LINE NUMBER = RUNS AT ONCE:\"\n170 print \"{158}  PRINT 2+2\":print \"{5}\"\n180 print \" FIX A LINE: CURSOR UP, EDIT, RETURN.\"\n190 goto 500\n200 print \" DISKS (THE 1541, DEVICE 8)\":print\n210 print \"{158}  LOAD\";q$;\"$\";q$;\",8\":print \"  LIST    {5}SHOW THE DIRECTORY\"\n220 print \"{158}  LOAD\";q$;\"NAME\";q$;\",8\":print \"  RUN\":print \"{5}\"\n230 print \" SAVE WHAT YOU TYPED:\":print \"{158}  SAVE\";q$;\"MYGAME\";q$;\",8\":print \"{5}\"\n240 print \" USE THE 1541 PANEL FOR MORE DISKS,\"\n250 print \" OR THE PROGRAM BUTTON TO COPY/PASTE.\"\n260 goto 500\n300 print \" COLOURS AND SCREEN\":print\n310 print \"{5} CTRL OR C= WITH 1-8 CHANGES COLOUR\"\n320 print \" CTRL+9 REVERSE ON, CTRL+0 OFF\":print\n330 print \"{158}  POKE 53280,0   {5}BORDER COLOUR\"\n340 print \"{158}  POKE 53281,0   {5}BACKGROUND\"\n350 print \"{158}  POKE 1024,1    {5}PUT AN 'A' TOP LEFT\"\n360 print \"{158}  POKE 55296,2   {5}...AND MAKE IT RED\":print \"{5}\"\n370 print \" PRESS SHIFT+C= TO SWAP CHARACTER SETS\"\n380 goto 500\n400 print \" SOUND AND SPRITES\":print\n410 print \"{158}  POKE 54296,15\":print \"  POKE 54277,9\"\n420 print \"  POKE 54273,40\":print \"  POKE 54276,17\":print \"{5}\"\n430 print \" THAT PLAYS A NOTE. POKE 54276,16\"\n440 print \" STOPS IT. TRY THE PIANO PROGRAM!\":print\n450 print \" SPRITES: SEE THE SPRITE EDITOR AND\"\n460 print \" THE SPRITE DEMO ON THE DEMO DISK.\"\n500 print:print \"{159} \";p;\"OF 4  - ANY KEY=NEXT  Q=QUIT\"\n510 get k$:if k$=\"\" then 510\n520 if k$=\"Q\" then poke 53280,14:poke 53281,6:print \"{147}{154}\":end\n530 p=p+1:if p>4 then p=1\n540 goto 30\n"
 },
 {
  "name": "PIANO",
  "src": "10 rem *** sid piano ***\n20 s=54272:poke 53280,0:poke 53281,0\n30 for i=0 to 24:poke s+i,0:next:poke s+24,15\n40 poke s+2,0:poke s+3,8:poke s+5,9:poke s+6,240\n50 wv=17:dim fq(13),mk(13)\n60 for i=0 to 12:read mk(i),fq(i):next\n70 data 10,4455,9,4720,13,5001,14,5298,18,5613,21,5947,22,6300,26,6675,25,7072,29,7493,30,7938,34,8410,37,8910\n80 print \"{147}{158}   S I D   P I A N O\":print\n90 print \"{5}    W E   T Y U\"\n100 print \"   {18}A{146} {18}S{146} {18}D{146} {18}F{146} {18}G{146} {18}H{146} {18}J{146} {18}K{146}\"\n110 print:print \"{159}   HOLD KEYS TO PLAY. WHITE KEYS:\"\n120 print \"   A S D F G H J K  (C D E F G A B C)\"\n130 print \"   SHARPS: W E T Y U (ROW ABOVE)\":print\n140 print \"{5}   1 TRI  2 SAW  3 PULSE  4 NOISE\"\n150 print \"   RUN/STOP TO QUIT\":print\n160 w$=\"TRIANGLE\":gosub 300\n170 k=peek(197):g=0\n180 for i=0 to 12:if k=mk(i) then g=1:poke s,fq(i) and 255:poke s+1,int(fq(i)/256)\n190 next\n200 poke s+4,wv+g-1\n210 get a$:if a$=\"1\" then wv=17:w$=\"TRIANGLE\":gosub 300\n220 if a$=\"2\" then wv=33:w$=\"SAWTOOTH\":gosub 300\n230 if a$=\"3\" then wv=65:w$=\"PULSE   \":gosub 300\n240 if a$=\"4\" then wv=129:w$=\"NOISE   \":gosub 300\n250 goto 170\n300 poke 781,15:poke 782,3:poke 783,0:sys 65520:print \"{158}WAVEFORM: \";w$;\"  \":return\n"
 },
 {
  "name": "ADDRESS BOOK",
  "src": "10 rem *** address book (saves to disk) ***\n20 poke 53280,6:poke 53281,6:dim n$(40),p$(40):nc=0:open 15,8,15\n30 print \"{147}{158}   A D D R E S S   B O O K\":print\n40 print \"{5}   1 ADD A CONTACT\"\n50 print \"   2 LIST CONTACTS\"\n60 print \"   3 SEARCH\"\n70 print \"   4 SAVE TO DISK (ADDRESSES)\"\n80 print \"   5 LOAD FROM DISK\"\n90 print \"   6 DISK STATUS\"\n100 print \"   7 QUIT\":print:print \"{158}   CONTACTS:\";nc\n110 get k$:if k$<\"1\" or k$>\"7\" then 110\n120 on val(k$) goto 200,300,400,500,600,700,800\n200 print \"{147}{5}\":input \"NAME\";a$:if a$=\"\" then 30\n210 input \"PHONE\";b$:if nc>=40 then print \"{28}BOOK IS FULL\":goto 290\n220 nc=nc+1:n$(nc)=a$:p$(nc)=b$:print \"{153}ADDED.\"\n290 for i=1 to 600:next:goto 30\n300 print \"{147}{5}\":if nc=0 then print \"NO CONTACTS YET.\":goto 390\n310 for i=1 to nc:print i;n$(i);\" \";p$(i):next\n390 print:print \"{158}PRESS ANY KEY\"\n392 get k$:if k$=\"\" then 392\n395 goto 30\n400 print \"{147}{5}\":input \"SEARCH FOR\";a$:f=0\n410 if nc=0 then 390\n420 for i=1 to nc:if left$(n$(i),len(a$))=a$ then print n$(i);\" \";p$(i):f=1\n430 next:if f=0 then print \"{28}NOT FOUND.\"\n440 goto 390\n500 print \"{147}{5}\":if nc=0 then print \"NOTHING TO SAVE.\":goto 390\n510 open 2,8,2,\"@0:ADDRESSES,S,W\":print#2,nc\n520 for i=1 to nc:print#2,n$(i):print#2,p$(i):next\n530 close 2:gosub 900:print \"SAVED\";nc;\"CONTACTS.\"\n540 goto 390\n600 print \"{147}{5}\":open 2,8,2,\"ADDRESSES,S,R\"\n610 gosub 900:if en<>0 then close 2:print \"{28}COULD NOT READ THE FILE.\":goto 390\n620 input#2,nc:for i=1 to nc:input#2,n$(i):input#2,p$(i):next\n630 close 2:print \"{153}LOADED\";nc;\"CONTACTS.\":goto 390\n700 print \"{147}{5}\":gosub 900:print \"DISK SAYS: \";en;em$:goto 390\n800 close 15:print \"{147}\":end\n900 input#15,en,em$,et,es:return\n"
 },
 {
  "name": "SPRITE EDITOR",
  "src": "10 rem *** sprite editor ***\n20 v=53248:poke 53280,0:poke 53281,0:dim b(23,20)\n30 for i=0 to 62:poke 832+i,0:next\n40 poke 2040,13:poke v+39,1:poke v+29,1:poke v+23,1:poke v,200:poke v+1,100:poke v+16,1:poke v+21,1\n50 gosub 700\n60 cx=0:cy=0\n70 gosub 800\n80 get k$:if k$=\"\" then 80\n90 gosub 850\n100 if k$=\"W\" and cy>0 then cy=cy-1\n110 if k$=\"S\" and cy<20 then cy=cy+1\n120 if k$=\"A\" and cx>0 then cx=cx-1\n130 if k$=\"D\" and cx<23 then cx=cx+1\n140 if k$=\" \" then b(cx,cy)=1-b(cx,cy):gosub 900\n150 if k$=\"C\" then for i=0 to 62:poke 832+i,0:next:for x=0 to 23:for y=0 to 20:b(x,y)=0:next:next:gosub 700\n160 if k$=\"P\" then 500\n170 if k$=\"Q\" then poke v+21,0:print \"{147}\":end\n180 goto 70\n500 print \"{147}{5}\":poke v+21,0\n510 print \"SPRITE DATA - COPY IT WITH CTRL/CMD-C:\":print \"{158}\"\n520 for r=0 to 8:l$=mid$(str$(1000+r*10),2)+\" DATA \"\n525 for j=0 to 6:l$=l$+mid$(str$(peek(832+r*7+j)),2):if j<6 then l$=l$+\",\"\n530 next:print l$:next\n540 print \"{5}\":print \"PRESS ANY KEY TO KEEP EDITING\"\n550 get k$:if k$=\"\" then 550\n560 poke v+21,1:gosub 700:goto 70\n700 print \"{147}{5} W A S D MOVE  SPACE TOGGLE  C CLEAR\"\n710 print \" P PRINT DATA  Q QUIT\"\n720 for y=0 to 20:for x=0 to 23:poke 1024+(y+3)*40+x+2,46:poke 55296+(y+3)*40+x+2,11:if b(x,y)=1 then poke 1024+(y+3)*40+x+2,160:poke 55296+(y+3)*40+x+2,7\n730 next:next:return\n800 q=1024+(cy+3)*40+cx+2:poke q,102:poke q+54272,1:return\n850 q=1024+(cy+3)*40+cx+2:poke q,46:poke q+54272,11:if b(cx,cy)=1 then poke q,160:poke q+54272,7\n860 return\n900 byt=832+cy*3+int(cx/8):bit=128/2^(cx and 7)\n910 if b(cx,cy)=1 then poke byt,peek(byt) or bit\n920 if b(cx,cy)=0 then poke byt,peek(byt) and (255-bit)\n930 gosub 850:return\n"
 }
